import hashlib, json, pathlib, subprocess
root = pathlib.Path('out/engine3d/phase26')
load = lambda p: json.loads(pathlib.Path(p).read_text(encoding='utf-8-sig'))
rows = [load(root/'benchmarks'/f'final-{key}.json') for key in 'ABCDEFGH']
for row in rows:
    story = load(root/'stories'/f"final-{row['id']}.json")
    row['problemCount'] = sum(n['role'] in ('PROBLEM','NEW_PROBLEM') for n in story['nodes'])
    if row['id'] == 'E':
        source_session = load(root/'research/live-E.json')
        if any('HTTP 429' in (entry.get('diagnostic') or '') for entry in source_session['searchTrace']):
            row['failureReason'] += '; provider HTTP 429'
checks = load(root/'analysis/checks.json')
assert len(checks) == 20, 'Finish all twenty commands before reporting'
replay = load(root/'replay/final.json')
anti = load(root/'analysis/anti-hardcode.json')
baseline = load(root/'baseline/baseline.json')
head = subprocess.check_output(['git','rev-parse','HEAD'], text=True).strip()
branch = subprocess.check_output(['git','branch','--show-current'], text=True).strip()
registry = dict(Engine3D=len(load('out/engine3d/catalog.json')), SFX=len(load('examples/sound/media-registry.json')['assets']), VISUAL=len(load('examples/visual/media-registry.json')['assets']))
useful = sum(r['physicalClaims'] > 0 and r['uniqueRelations'] >= 2 for r in rows)
adequate = sum(r['potential'] in ('ADEQUATE','RICH') for r in rows)
eligible = sum(r['writerEligible'] for r in rows)
full = len(checks) == 20 and all(r['exitCode'] == 0 for r in checks)
tests = next(r['tests'] for r in checks if r['command'] == 'check:engine3d')
new_tests = next(r['tests'] for r in checks if r['command'] == 'check:causal-curiosity')
a, b = rows[:2]
fixture_pass = full and new_tests >= 69
gates = [
 ('P1', head == '19d55834c38d0fdf3dea86c4708cdf0db637dd63' and branch == 'main', 'Checkpoint e branch conferidos; árvore inicialmente limpa antes de editar'),
 ('P2', baseline['sessions'][0]['admittedFacts'] == 3, 'Baseline histórica + 872 testes; snapshots A/B preservados'),
 ('P3', fixture_pass, 'Extração PT/EN em fixtures fictícias'),
 ('P4', fixture_pass, 'Negação, modalidade, condicionais e contrações'),
 ('P5', fixture_pass, 'Identidade, alias explícito, seções, captions e sujeitos não resolvidos'),
 ('P6', replay['passed'], 'Grafo reconstruído e fingerprints comparados'),
 ('P7', fixture_pass, 'Problema/causa/solução com provas em fixtures; sem cadeia real inventada'),
 ('P8', fixture_pass, 'StoryPotential determinístico; ausências como GAP'),
 ('P9', fixture_pass and replay['passed'], 'Plano sem naive attempt ou história sintetizados'),
 ('P10', a['writerEligible'] and b['writerEligible'], 'Rota CAUSAL_CURIOSITY_PROCESS libera roteiro em A/B'),
 ('P11', all('groundedRatio' in r['writerMetrics'] for r in rows), 'Razão por frases e unidades de conhecimento medidas'),
 ('P12', a['admittedFacts'] > 3 and a['physicalClaims'] > 1, 'Poço: 3→4 unidades; 1→2 relações físicas'),
 ('P13', b['physicalClaims'] > 0 and b['writerEligible'], 'Turbina: mecanismo útil e Writer; referência correta é o replay final Phase25'),
 ('P14', useful >= 5, f'{useful}/8 com mecanismo útil; mínimo 5/8'),
 ('P15', adequate >= 4, f'{adequate}/8 ADEQUATE/RICH; mínimo 4/8'),
 ('P16', useful >= 5 and fixture_pass, 'Fixtures/paráfrases PASS; generalização real continua fraca'),
 ('P17', fixture_pass and replay['passed'], 'Cold gravado, ficção e hipótese sem relaxamento'),
 ('P18', fixture_pass and replay['passed'], 'Replay zero rede, prova e adulteração re-assinada'),
 ('P19', anti['passed'], 'Scanner ampliado + controle negativo'),
 ('P20', full, f'{tests} testes únicos; 20/20 comandos'),
]
complete = all(passed for _,passed,_ in gates)
summary = dict(phase26Complete=complete,implementationGate=fixture_pass and replay['passed'] and anti['passed'],baseCheckpoint=head,branch=branch,
 usefulMechanismBenchmarks=useful,adequateOrRichBenchmarks=adequate,writerEligibleBenchmarks=eligible,tests=tests,newTests=new_tests,commandsPassed=sum(r['exitCode']==0 for r in checks),registry=registry,autonomy='LEVEL4C+',phase27='NOT_STARTED',gates=[dict(id=k,status='PASS' if v else 'FAIL',evidence=why) for k,v,why in gates])
(root/'analysis/final-status.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
(root/'analysis/implementation-gates.json').write_text(json.dumps(summary['gates'],indent=2),encoding='utf-8')
def table(headers, data):
    clean=lambda x:('—' if x is None else str(x)).replace('|','/').replace('\n',' ')
    return '\n\n| '+' | '.join(headers)+' |\n|'+'|'.join('---' for _ in headers)+'|\n'+'\n'.join('| '+' | '.join(clean(c) for c in row)+' |' for row in data)+'\n\n'
benchmark_table = table(['ID / Topic','Intent / Route','Research','Sources / useful','Facts / relations / physical','Causal / problem / solution','Potential','Writer / reason'], [
 (r['id']+' — '+r['topic'],r['intent']+' / '+r['route']['level'],r['researchStatus'],str(r['sources'])+' / '+str(r['contributingSources']),f"{r['admittedFacts']} / {r['uniqueRelations']} / {r['physicalClaims']}",f"{r['causalRelations']} / {r['problemCount']} / {r['solutionRelations']}",r['potential'],r['writerStatus']+' / '+(r['failureReason'] or '—')) for r in rows])
comparison = table(['Metric — poço','Phase25','Phase26','Delta'],[
 ('accepted sources',5,a['acceptedSources'],a['acceptedSources']-5),('contributing sources',1,a['contributingSources'],a['contributingSources']-1),('grounded knowledge units',3,a['admittedFacts'],a['admittedFacts']-3),('unique relations','not measured historically',a['uniqueRelations'],'N/A'),('physical claims',1,a['physicalClaims'],a['physicalClaims']-1),('causal claims',1,a['causalRelations'],a['causalRelations']-1),('grounded sentence units',3,a['writerMetrics']['groundedSentenceUnits'],a['writerMetrics']['groundedSentenceUnits']-3),('editorial filler units',5,a['writerMetrics']['editorialUnits'],a['writerMetrics']['editorialUnits']-5),('grounded sentence ratio','37.5%',f"{a['writerMetrics']['groundedRatio']*100:.2f}%",f"{(a['writerMetrics']['groundedRatio']-3/8)*100:+.2f} pp"),('knowledge-unit ratio','37.5%',f"{a['writerMetrics']['groundedKnowledgeUnits']/(a['writerMetrics']['groundedKnowledgeUnits']+a['writerMetrics']['editorialUnits'])*100:.2f}%",'different denominator; explicitly shown'),('words',111,a['writerMetrics']['words'],a['writerMetrics']['words']-111),('facts/source',3/5,round(a['factsPerSource'],4),round(a['factsPerSource']-3/5,4)),('Writer / visual gate','PRODUCTION_ELIGIBLE / measured MP4',a['writerStatus']+' / not evaluated','different production scope')])
performance = table(['ID','queries','results','fetches','bytes','sources','useful','facts/source','facts/1000 chars','measured processing ms'],[(r['id'],r['acquisition']['queries'],r['acquisition']['results'],r['acquisition']['fetches'],r['acquisition']['bytes'],r['sources'],r['contributingSources'],round(r['factsPerSource'],4),round(r['usableFactsPer1000Chars'],4),round(r['acquisition']['timeMs'],1)) for r in rows])
extraction_path = root/'analysis/extraction.json'
if extraction_path.exists():
    performance += table(['ID','evidence extracted','all candidates','mechanism candidates','mechanism admitted'],[(r['id'],r['evidenceExtracted'],r['factCandidatesExtracted'],r['mechanismCandidatesExtracted'],r['mechanismFactsAdmitted']) for r in load(extraction_path)])
quality = table(['Dimension','Assessment'],[(name,grade) for name,grade in [
 ('PROCESS RESEARCH','WEAK'),('MECHANISM EXTRACTION','ACCEPTABLE'),('KNOWLEDGE DENSITY','WEAK'),('SUBJECT IDENTITY','ACCEPTABLE'),('CAUSAL REASONING','ACCEPTABLE'),('PROBLEM/SOLUTION MODELING','ACCEPTABLE'),('SEQUENCE UNDERSTANDING','WEAK'),('SPATIAL UNDERSTANDING','ACCEPTABLE'),('STORY POTENTIAL','ACCEPTABLE'),('CURIOSITY STORYTELLING','WEAK'),('WRITER','ACCEPTABLE'),('TRACEABILITY','STRONG'),('GENERALIZATION','WEAK'),('DETERMINISM','STRONG'),('REPLAY','STRONG'),('PROVENANCE','STRONG'),('SAFETY','GOOD'),('ANTI-HARDCODE','STRONG'),('LEGACY COMPATIBILITY','STRONG'),('OVERALL AUTONOMY','ACCEPTABLE')]])
sections = [
 ('Objective',f'**PHASE26 COMPLETE: {"YES" if complete else "NO"} — resultado parcial.** Implementação e regressão passam; os gates reais P14/P15/P16 não passam. Foram entregues extração de mecanismo v2, conhecimento causal, plano editorial e Writer específico de curiosidade. A bateria real alcançou {useful}/8 com mecanismo útil, {adequate}/8 ADEQUATE/RICH e {eligible}/8 Writer eligible. Nenhum resultado foi completado com conhecimento interno.'),
 ('Starting State','Em 2026-10-29: `main`, HEAD exatamente `19d55834c38d0fdf3dea86c4708cdf0db637dd63`, working tree CLEAN antes da primeira edição. Lidos integralmente CLONAI_HANDOFF e PHASE23/24/25_REPORT; auditados Topic, Research, Writer, Semantics, Narrative, Auto Director, Vertical, DirectedSequence, demonstração, catálogo e replay. A captura `baseline/baseline.json` foi escrita após adicionar a ferramenta de instrumentação; seu status Git inclui essa ferramenta, não substitui a verificação inicial. Não houve reset/clean/commit/push/tag/remote.'),
 ('Phase25 Lessons','Baseline fresca: 872 testes. Poço: 3 fatos, 1 claim física, 5 editoriais, 111 palavras; turbina bloqueada no processamento final por ausência de mecanismo admissível. O arquivo de aquisição secundária contém uma versão anterior ao conserto de truncagem (3 tuplas, incluindo uma inválida); o trace `probe-turbine-final` e a reconstrução com o código legado são a referência correta. Essa distinção está em `baseline/secondary-checkpoint-rebuild.json`; nenhum artefato histórico foi editado.'),
 ('Architecture','Opt-in `sourcePolicy.mechanismVersion: 2`, apenas PROCESS e researchVersion >=2; não existe Research v5. Contratos FactType/Modality/SourceSpan, admissibilidade, origens, snapshots e transporte foram reutilizados. `mechanism-language.ts` centraliza gramática; `mechanism-v2.ts` extrai; `process-planning.ts` define lacunas/queries; `src/curiosity/{knowledge,story,replay}.ts` constrói e verifica; `src/writer/curiosity.ts` escreve. `cli/curiosity.ts` aceita tópico factual como única entrada necessária. `npm run curiosity:run -- "<topic>" [outputDirectory] [recordedSession.json]`.'),
 ('Mechanism Extraction v2','Regras fechadas para voz ativa/passiva, causa explícita, função, prevenção, permissão, composição, fluxo, transformação, ação mecânica, localização e antes/depois com dois eventos explícitos. Sem inferência de causalidade por coocorrência. Negações, contrações negativas, prevenção falha, fórmulas/quantidades e referências não resolvidas abstêm. Conjunção “e” não é cópula “é”; tempo decorrido não vira etapa. A auditoria real removeu notas de navegação, sujeitos relativos e definições de instâncias alheias que os primeiros fixtures não cobriam. Resultados preliminares não são resultados finais.'),
 ('Language Coverage','PT-BR e EN cobertos por fixtures e integração EvidencePack→Story→Writer. Corrigida a extração do assunto de “How does … work?”, que apagava toda a pergunta. Modalidade e seus marcadores literais são preservados. Não há tradução interna; o roteiro em inglês usa superfícies inglesas. A bateria live A–H é PT-BR. O Semantic Engine visual legado continua pt-BR; não se afirma produção visual inglesa.'),
 ('Evidence Semantics','Cada relação contém fact IDs, evidências, sourceId, locator, SHA-256 do snapshot, span exato, contexto de heading/alias, originGroupId, status, modalidade, qualifiers e contexto temporal ou null. A evidência usa a frase completa para preservar escopo e condições. Só facts policy-admitted entram em conhecimento. Source title/alias delimita escopo, nunca cria automaticamente HAS_COMPONENT. Alias exige conector literal e os dois nomes; nome parecido não basta.'),
 ('Causal Knowledge','MechanismKnowledge deriva métricas e cobertura qualitativa. CausalConstructionGraph contém exclusivamente arestas literais com provas. Requer mecanismo físico e uma dimensão complementar para PROCESS READY; três frases de fluxo redundante ficam THIN. Nem toda categoria é obrigatória. Os nós conservam sujeitos distintos; contexto do sistema não equivale a identidade de entidade.'),
 ('Problem/Solution Modeling','SOLVES/PREVENTS/FAILS_BECAUSE têm prova literal. Cadeia SOLVES→CAUSES→SOLVES pode marcar NEW_PROBLEM/NEXT_SOLUTION quando participantes coincidem. Ligações de participante são navegação editorial, não novas conclusões factuais ou cronologia. Isso passa em fixtures fictícias. Nenhuma cadeia real problema/solução foi demonstrada em A–H; ausência permanece GAP.'),
 ('Story Potential','RICH/ADEQUATE/THIN/INSUFFICIENT são heurísticas determinísticas de suporte. Propósito explícito com operação física e conhecimento complementar pode sustentar ADEQUATE sem problema artificial. RICH exige mais relações e dimensões. O rating não certifica naturalidade, progressão ou qualidade final; a review mede essas dimensões separadamente.'),
 ('Curiosity Story Planning','GOAL, SETUP, ATTEMPT, PROBLEM, EXPLANATION, SOLUTION, STATE_CHANGE, NEW_PROBLEM, NEXT_SOLUTION e PAYOFF somente quando relações permitem. Nenhuma naive attempt é sintetizada; história da invenção fica vazia. Ordem de discurso é explicitamente EDITORIAL_DISCOURSE_ONLY. Fonte próxima, mesmo artigo ou sequência de frases não prova causa ou ordem física.'),
 ('Writer Integration','Rota exportada CAUSAL_CURIOSITY_PROCESS; um hook não assertivo e frases completas source-exact. Não há preenchimento para 110 palavras. SCRIPT_GROUNDED indica elegibilidade narrativa; visual/MP4 são gates separados. KNOWLEDGE_LIMITED indica conteúdo/rota insuficiente ou comprimento abaixo do alvo; preview parcial não é elegibilidade. Surface realization segura ainda soa documental; não é um paraphrase engine geral.'),
 ('Semantic Handoff','Cada relação selecionada acompanha sentence IDs, story node IDs e prova no handoff, junto do grafo legado real. Nenhuma claim oculta é injetada no compilador. Relações não suportadas pelo legado ficam listadas e visualExecution=NOT_EVALUATED. A representação preserva o que foi extraído; não demonstra que toda a sintaxe da frase original foi compreendida. Cobertura semântica geral permanece parcial.'),
 ('Presenter Intent','PRESENTER_CONTEXT/OBSERVES/POINTS/REACTS/REVEALS/PAYOFF são intenções semânticas. Não houve personagem, rigging ou animação novos.'),
 ('World Context Intent','ESTABLISH_WORLD, SHOW_SYSTEM_IN_CONTEXT, SHOW_INTERNAL_STRUCTURE, CUTAWAY_REQUIRED, RETURN_TO_WORLD e SHOW_FINAL_SYSTEM quando pertinentes. Sem coordenadas, assets, cenário ou renderer novos.'),
 ('Persistent System Intent','O plano indica continuidade de contexto em vários nós; CONTEXT_NOT_IDENTITY impede assumir conexões físicas não provadas. Este é apenas o contrato de entrada para direção futura. Não foi implementado mundo persistente.'),
 ('Benchmark Battery','Oito temas permanentes em `tools/phase26/benchmarks.ts`, exclusivamente inputs de operador. Primeira coleta A–H preservada em `research/live-*.json`. A/B tiveram coleta final após hardening (`live-final-*`). C–H usam snapshots live originais e processamento final offline. Não se alega que a antiga decisão de aquisição foi recalculada com a gramática nova. Coletas e falhas de desenvolvimento ficam preservadas. Nenhuma coleta Cold foi refeita.'),
 ('Per-Benchmark Results',benchmark_table+'Critério “mecanismo útil”: ao menos uma relação física explícita e duas relações únicas. Facts desta tabela são unidades de mecanismo admitidas, não todo ruído estrutural do EvidencePack. Fontes aceitas não são automaticamente fontes que contribuem fatos.'),
 ('Phase25 Comparison',comparison+'Comparações live envolvem observações distintas. `recorded-A/B` isola a gramática sobre snapshots Phase25. Não se inventa baseline para C–H nem para métricas que Phase25 não mediu. O yield por fonte do poço caiu apesar do pequeno ganho de conhecimento: mais aquisição não resolveu o gargalo.'),
 ('Poço Result',f"{a['admittedFacts']} unidades, {a['physicalClaims']} físicas, {a['causalRelations']} causal, {a['contributingSources']} fonte útil. {a['writerMetrics']['words']} palavras, {a['writerMetrics']['editorialUnits']} editorial, grounded sentence ratio {a['writerMetrics']['groundedRatio']:.4f}. Ganho modesto e honesto; não atingiu 6–15 unidades, progressão rica ou payoff funcional. O script curto não foi inflado e não houve TTS/render novo. Duração apresentada é estimativa, não áudio medido."),
 ('Turbine Result',f"{b['admittedFacts']} relações, {b['physicalClaims']} física, {b['causalRelations']} funcional, {b['constraintRelations']} restrição. Writer {b['writerStatus']}, {b['writerMetrics']['words']} palavras; supera o bloqueio específico da Phase25. Continua com uma origem, sem sequência ou cadeia problema/solução. Não demonstra vídeo mecânico DIRECT."),
 ('Cross-Domain Generalization',f'**WEAK no mundo real.** {useful}/8 mecanismos úteis e {eligible}/8 Writer eligible. Fixtures de diferentes sistemas e verbos passam; isso não substitui os benchmarks reais. C tem alias/escopo e sintaxe de mecanismo limitados; D não tem identidade suficiente para os documentos encontrados; F/G/H não produziram mecanismos admissíveis com a gramática e escopo finais. Não se ampliou um whitelist de nomes nem se promoveu uma frase ambígua para elevar contagens.'),
 ('Paraphrase Generalization','PASS para os pares de turbina e refrigeração: requisitos, risco e rota equivalentes. Queries e conteúdo descoberto podem diferir; não se exige fingerprint igual. Testes em `causal-curiosity.test.ts`.'),
 ('Cold Regression','PASS: STRICT, ranking route, quorum, residency, eligibility e superlativo global preservados; replay da sessão Phase23. Nenhum Cold live. O campo mechanismVersion é recusado em RANKING.'),
 ('Fiction Regression','PASS: eventos ficcionais não se tornam EvidenceRequirement factual. A CLI de curiosidade exige processo factual; roteamento criativo existente permanece indisponível e isolado.'),
 ('Hypothetical Regression','PASS: premissa hipotética preservada e não afirmada; consequências não viram observações. Modality HYPOTHETICAL e condicionais permanecem explícitas.'),
 ('Historical Safety','PASS em fixtures e auditoria: função não vira motivo histórico. Não há história inventada, tentativa popular presumida ou invenção inferida de engenharia.'),
 ('Replay',f"{'PASS' if replay['passed'] else 'FAIL'}: {replay['networkCallsAttempted']} tentativas de rede. Reconstituídos pack, knowledge, graph, story, Writer, script e trace dos oito resultados finais. A/B também passam pelo replay completo do processamento da aquisição final; C–H têm aquisição pré-hardening validada e seu processamento final reexecutado, não equivalência com o antigo pack de desenvolvimento. Sessões históricas e 12 stages puros Phase25 conferidos. `replay/final.json`."),
 ('Provenance','PASS: cadeia de hashes e IDs liga roteiro→story→knowledge→facts→evidence→snapshot. `verifyProcessAcquisition` exige correspondência exata com snapshot adquirido. Re-signing de relação, nó, link, Writer ou pack não basta: rederivação é comparada. Hashes dos relatórios 23/24/25, handoff, package-lock e vídeos históricos conferidos no replay; nenhum histórico reescrito.'),
 ('Security','Transporte seguro existente preservado: SSRF, DNS/pinning, redirects, robots, MIME, charset, bytes e timeouts. Nada de OCR/PDF/JS universal, bypass ou APIs pagas. Texto externo é dado. HTTP 429 observado em E; foi introduzida parada conservadora de provider na sessão opt-in, comprovada por mock sem rede. A coleta E antiga preserva a falha; não houve tentativa de contornar o limite. Quorum/Claim Risk não foram reduzidos. Quantidades/fórmulas são recusadas pelo novo caminho e dependem das políticas já existentes.'),
 ('Anti-hardcode',f"{'PASS' if anti['passed'] else 'FAIL'}: {anti['scannedFiles']} arquivos runtime, {len(anti['blockers'])} BLOCKER, controle negativo detectado. O scanner cobre os oito temas, frases finais e URLs efetivamente adquiridas. Ocorrências pré-existentes em léxico genérico e recusa legada são classificadas e comparadas ao checkpoint; não há exceção para código novo específico de benchmark. Fixtures, harness e relatórios podem conter tópicos."),
 ('Performance',performance+'Tempos de processamento ocorreram sob pressão de memória e concorrência inicial; não são um benchmark comparável de velocidade com Phase25. A análise auxiliar foi interrompida, snapshots preservados e processamento restante separado em processos sequenciais com heap limitado. Large outputs continuam ignorados. Nenhum custo pago novo.'),
 ('Tests',f'**{tests} testes únicos; {new_tests} novos; {sum(r["exitCode"]==0 for r in checks)}/20 comandos PASS.** Fixtures fictícias e providers mockados; unidades sem internet. Houve repetição da suíte e dos checks relacionados após corrigir o assunto inglês. '+table(['Command','Exit','Tests','Seconds'],[(r['command'],r['exitCode'],r['tests'],r['seconds']) for r in checks])+table(['Gate','Result','Evidence'],[(k,'PASS' if v else 'FAIL',why) for k,v,why in gates])),
 ('Registry',f"Engine3D {registry['Engine3D']} / SFX {registry['SFX']} / VISUAL {registry['VISUAL']} — inalterados. Catálogo consultado, nenhuma necessidade de asset novo; nenhum vídeo novo ou visual polish."),
 ('Compatibility','Ausência de mechanismVersion mantém extração/query/Writer históricos. A mudança geral adicional é o conserto da noun phrase em perguntas inglesas; Cold e requests PT antigos continuam iguais. Sem dependências/lock/versões novas; sem alteração de Engine3D/Three/R3F/Remotion, voz ou aprovações de mídia.'),
 ('Limitations','Gramática fechada e baixo recall; identidade por título/alias explícito recusa fontes potencialmente pertinentes com nomes diferentes. Sem coreferência geral, tradução, síntese abstrativa, entendimento universal de cláusulas ou parser universal de componentes. Zero cadeias reais problema/solução e zero segunda origem útil. Rating de potencial pode ser ADEQUATE com pouca progressão; o review deixa essa falta explícita. O Writer source-exact ainda não entrega a qualidade falada desejada. Goldens/snapshots grandes são locais e precisam ser transportados separadamente do Git. Não se conclui Phase26 integralmente.'),
 ('Honest Assessment',quality+'A arquitetura demonstrou relações grounded e preservação de evidência; a generalização real e a história causal rica continuam fracas. Os gates reprovados não foram renomeados como sucesso de implementação.'),
 ('Autonomy','**LEVEL4C+ mantido.** Nenhuma promoção automática. Dois roteiros admissíveis e gramática determinística não provam autonomia superior.'),
 ('Biggest Remaining Bottleneck','Baixo recall contextual de mecanismos na prosa real, principalmente identidade de sistema e relações entre orações sem truncagem ou referências adivinhadas.'),
 ('Phase27 Recommendation','Priorizar o fechamento dos gaps de conhecimento da bateria antes de ampliar os visuais. O handoff de intents existe, mas a cobertura atual não sustenta uma implementação visual generalista. **Phase27 NOT STARTED.** Working tree deixado para revisão, sem commit/push.'),
]
report = '# Phase 26 — Causal Curiosity Storytelling — Partial final report\n\nData: 2026-10-29. Base imutável: `'+head+'`. Branch: `'+branch+'`.\n\n'
